import openpyxl

wb = openpyxl.load_workbook('2_102-20_answer_template_5699_input.xlsx', data_only=False)
gold = openpyxl.load_workbook('/mnt/hhq/data/answer_files/2_102-20_answer.xlsx', data_only=False)

# Compare formulas
for name in ['Raw Data', 'Expected result']:
    ws = wb[name]
    gw = gold[name]
    for row in ws.iter_rows(min_row=1, max_row=ws.max_row, min_col=1, max_col=9):
        for c in row:
            g = gw[c.coordinate]
            if c.value is not None and isinstance(c.value, str) and c.value.startswith('='):
                if c.value != g.value:
                    print('FORMULA MISMATCH', name, c.coordinate, repr(c.value), repr(g.value))
            elif g.value is not None and isinstance(g.value, str) and g.value.startswith('='):
                if c.value != g.value:
                    print('FORMULA MISSING/MISMATCH', name, c.coordinate, repr(c.value), repr(g.value))

# Count data cells (non-formula, non-None values) and compare
for name in ['Raw Data', 'Expected result']:
    ws = wb[name]
    gw = gold[name]
    diffs = []
    for row in ws.iter_rows(min_row=1, max_row=ws.max_row, min_col=1, max_col=9):
        for c in row:
            g = gw[c.coordinate]
            if c.value != g.value:
                diffs.append((c.coordinate, repr(c.value), repr(g.value)))
    print(name, 'diffs:', diffs)

# count non-empty data cells
for name in ['Raw Data', 'Expected result']:
    ws = wb[name]
    cnt = sum(1 for row in ws.iter_rows(min_row=1, max_row=ws.max_row, min_col=1, max_col=9) for c in row if c.value is not None and not (isinstance(c.value, str) and c.value.startswith('=')))
    print(name, 'data cells count', cnt)
