import openpyxl
wb = openpyxl.load_workbook('2_102-20_answer_template_5699_input.xlsx', data_only=False)
gold = openpyxl.load_workbook('/mnt/hhq/data/answer_files/2_102-20_answer.xlsx', data_only=False)

def style_tuple(c):
    return (c.number_format, c.font.bold, c.font.name, c.font.sz,
            c.fill.patternType, c.fill.fgColor.rgb, c.fill.bgColor.rgb,
            c.alignment.horizontal, c.alignment.vertical,
            c.border.left.style, c.border.right.style, c.border.top.style, c.border.bottom.style)

diffs = []
for name in ['Raw Data', 'Expected result']:
    ws = wb[name]
    gw = gold[name]
    for row in ws.iter_rows(min_row=1, max_row=ws.max_row, min_col=1, max_col=9):
        for c in row:
            g = gw[c.coordinate]
            if style_tuple(c) != style_tuple(g):
                diffs.append((name, c.coordinate, style_tuple(c), style_tuple(g)))
print('style diffs count', len(diffs))
for d in diffs[:50]:
    print(d)
